using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using Microsoft.Win32;

namespace Aster {
 public partial class Desktop {
  bool exitRequested;System.Windows.Forms.NotifyIcon tray;
  void SetupVault(){string xml=@"<Grid xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' x:Name='VaultPage' Visibility='Collapsed'><Grid.RowDefinitions><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='Auto'/><RowDefinition Height='*'/><RowDefinition Height='Auto'/></Grid.RowDefinitions><StackPanel><TextBlock Text='Kho ứng dụng của bạn.' Style='{DynamicResource Title}'/><TextBlock Text='Ứng dụng và game, chỉ điểm khởi chạy EXE. Không đưa tài nguyên ingame vào kho.' Style='{DynamicResource Subtitle}'/></StackPanel><WrapPanel Grid.Row='1' Margin='0,0,0,16'><ComboBox x:Name='VaultGroup' Width='170' SelectedIndex='0'><ComboBoxItem Content='Ứng dụng'/><ComboBoxItem Content='Game'/></ComboBox><Button x:Name='VaultAdd' Content='+ Thêm EXE' Background='{DynamicResource PrimaryFill}' Foreground='#101A2B'/><Button x:Name='VaultLaunch' Content='Mở mục đã chọn'/><Button x:Name='VaultRemove' Content='Gỡ khỏi kho'/><Button x:Name='HideTray' Content='Ẩn xuống khay'/></WrapPanel><TextBlock x:Name='VaultSummary' Grid.Row='2' Foreground='{DynamicResource Muted}' Margin='0,0,0,16'/><ListBox x:Name='VaultItems' Grid.Row='3' Background='Transparent' BorderThickness='0' SelectionMode='Extended' ScrollViewer.HorizontalScrollBarVisibility='Disabled'><ListBox.ItemsPanel><ItemsPanelTemplate><WrapPanel/></ItemsPanelTemplate></ListBox.ItemsPanel><ListBox.ItemTemplate><DataTemplate><Border Width='180' Height='176' Background='{DynamicResource Surface}' CornerRadius='14' Padding='18' Margin='4'><StackPanel><Image Source='{Binding Icon}' Width='64' Height='64' HorizontalAlignment='Center' Margin='0,0,0,16'/><TextBlock Text='{Binding Name}' FontWeight='SemiBold' TextTrimming='CharacterEllipsis' TextAlignment='Center'/><TextBlock Text='{Binding Kind}' Foreground='{DynamicResource Muted}' FontSize='11' TextAlignment='Center' Margin='0,6,0,0'/></StackPanel></Border></DataTemplate></ListBox.ItemTemplate></ListBox><TextBlock Grid.Row='4' Text='Gỡ khỏi kho chỉ bỏ liên kết; file EXE và ứng dụng trên máy vẫn được giữ nguyên.' Foreground='{DynamicResource Muted}' Margin='0,16,0,0' TextWrapping='Wrap'/></Grid>";
   var grid=(Grid)XamlReader.Parse(xml);Find<Grid>("PageHost").Children.Add(grid);RegisterTree(grid);var nav=(StackPanel)Find<Button>("NavApps").Parent;var b=new Button {Content="\uE71D   Kho ứng dụng",Style=(Style)w.Resources["Nav"]};w.RegisterName("NavVault",b);nav.Children.Insert(nav.Children.IndexOf(Find<Button>("NavApps")),b);b.Click+=(s,e)=>{Navigate("Vault");RefreshVault();};
   Click("VaultAdd",()=>{var dialog=new OpenFileDialog {Title="Thêm file mở ứng dụng / game",Filter="File EXE|*.exe",Multiselect=true};if(dialog.ShowDialog(w)!=true)return;string group=Find<ComboBox>("VaultGroup").SelectedIndex==1?"Game":"Ứng dụng";foreach(string path in dialog.FileNames){if(!path.EndsWith(".exe",StringComparison.OrdinalIgnoreCase))continue;var existing=state.Settings.Shortcuts.FirstOrDefault(s=>s.Path.Equals(path,StringComparison.OrdinalIgnoreCase));if(existing==null)state.Settings.Shortcuts.Add(new AppShortcut {Name=Path.GetFileNameWithoutExtension(path),Path=path,Group=group});else existing.Group=group;}state.Save();RefreshVault();});
   Click("VaultRemove",()=>{var paths=Find<ListBox>("VaultItems").SelectedItems.Cast<Entry>().Select(e=>e.Path).ToList();state.Settings.Shortcuts.RemoveAll(s=>paths.Contains(s.Path,StringComparer.OrdinalIgnoreCase));state.Save();RefreshVault();});Click("VaultLaunch",()=>{var item=Find<ListBox>("VaultItems").SelectedItem as Entry;if(item!=null)OpenEntry(item);});Find<ListBox>("VaultItems").MouseDoubleClick+=(s,e)=>{var item=Find<ListBox>("VaultItems").SelectedItem as Entry;if(item!=null)OpenEntry(item);};Find<ListBox>("VaultItems").SelectionChanged+=(s,e)=>Details(Find<ListBox>("VaultItems").SelectedItem as Entry);Find<ComboBox>("VaultGroup").SelectionChanged+=(s,e)=>RefreshVault();Click("HideTray",HideToTray);
  }
  void RefreshVault(){string group=Find<ComboBox>("VaultGroup").SelectedIndex==1?"Game":"Ứng dụng";var all=state.Settings.Shortcuts.Where(s=>s.Path.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)).GroupBy(s=>s.Path,StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();var rows=new List<Entry>();foreach(var shortcut in all.Where(s=>group=="Game"?s.Group=="Game"||s.Group=="Game / launcher":s.Group!="Game"&&s.Group!="Game / launcher")){if(File.Exists(shortcut.Path)){var item=Fs.Get(shortcut.Path);item.Name=shortcut.Name;item.Kind=group;item.Context=Path.GetDirectoryName(shortcut.Path);rows.Add(item);}}Find<ListBox>("VaultItems").ItemsSource=rows;Find<TextBlock>("VaultSummary").Text=rows.Count+" "+group.ToLowerInvariant()+" đang hiển thị · Kho có "+all.Count+" EXE · Nhấp đúp để mở";}
  void SetupStartupTray(){var panel=(StackPanel)Find<ScrollViewer>("SettingsPage").Content;var title=Text("Khởi động & khay hệ thống",16);title.Margin=new Thickness(0,22,0,12);panel.Children.Insert(2,title);var startup=new CheckBox {Content="Khởi động Aster cùng Windows",IsChecked=state.Settings.Startup};var hide=new CheckBox {Content="Ẩn xuống khay khi thu nhỏ hoặc đóng cửa sổ",IsChecked=state.Settings.MinimizeToTray};w.RegisterName("StartupChoice",startup);w.RegisterName("TrayChoice",hide);panel.Children.Insert(3,startup);panel.Children.Insert(4,hide);Find<Button>("SaveSettings").Click+=(s,e)=>{state.Settings.Startup=startup.IsChecked==true;state.Settings.MinimizeToTray=hide.IsChecked==true;state.Save();ApplyStartup();SetStatus("Đã lưu · Khởi động cùng Windows: "+(state.Settings.Startup?"bật":"tắt")+" · Khay hệ thống: "+(state.Settings.MinimizeToTray?"bật":"tắt"));};w.StateChanged+=(s,e)=>{if(w.WindowState==WindowState.Minimized&&state.Settings.MinimizeToTray)HideToTray();};}
  void ApplyStartup(){string realState=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aster");if(!state.Root.Equals(realState,StringComparison.OrdinalIgnoreCase))return;try{using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(state.Settings.Startup)key.SetValue("Aster","\""+Process.GetCurrentProcess().MainModule.FileName+"\""+(state.Settings.MinimizeToTray?" --tray":""));else key.DeleteValue("Aster",false);}}catch(Exception e){Error("Không lưu được khởi động cùng Windows: "+e.Message);}}
  public void HideToTray(){if(tray==null){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Aster.ico"))using(var icon=new System.Drawing.Icon(stream)){tray=new System.Windows.Forms.NotifyIcon {Icon=(System.Drawing.Icon)icon.Clone(),Text="Aster · Kho ứng dụng & dữ liệu"};}tray.DoubleClick+=(s,e)=>w.Dispatcher.BeginInvoke(new Action(RestoreFromTray));var menu=new System.Windows.Forms.ContextMenuStrip();menu.Items.Add("Mở Aster",null,(s,e)=>w.Dispatcher.BeginInvoke(new Action(RestoreFromTray)));menu.Items.Add("Thoát Aster",null,(s,e)=>w.Dispatcher.BeginInvoke(new Action(()=>{exitRequested=true;w.Close();})));tray.ContextMenuStrip=menu;}tray.Visible=true;w.ShowInTaskbar=false;w.Hide();}
  void RestoreFromTray(){exitRequested=false;w.ShowInTaskbar=true;w.Show();w.WindowState=WindowState.Normal;w.Activate();if(tray!=null)tray.Visible=false;}
 }
}

